def is_balanced(brackets):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in brackets:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if stack == [] or mapping[char] != stack.pop():
                return False
        else:
            return False
    return stack == []
```

